import{i as e,r as t,s as n,t as r}from"./app-DuH0mZgh.js";var i=JSON.parse(`{"path":"/AOI%E5%B9%BF%E6%92%AD%E4%B8%8E%E6%B6%88%E6%81%AF%E5%8E%BB%E9%87%8D.html","title":"AOI广播与消息去重","lang":"en-US","frontmatter":{},"filePathRelative":"AOI广播与消息去重.md","git":{"createdTime":1773827303000,"updatedTime":1773827303000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"},{"name":"Claude Opus 4.6 (1M context)","username":"","email":"noreply@anthropic.com","commits":1}]}}`),a={name:`AOI广播与消息去重.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="aoi广播与消息去重" tabindex="-1"><a class="header-anchor" href="#aoi广播与消息去重"><span>AOI广播与消息去重</span></a></h1><h2 id="目录" tabindex="-1"><a class="header-anchor" href="#目录"><span>目录</span></a></h2><ul><li><a href="#%E5%B9%BF%E6%92%AD%E7%B1%BB%E5%9E%8B">广播类型</a></li><li><a href="#%E6%B6%88%E6%81%AF%E5%8E%BB%E9%87%8D%E7%AD%96%E7%95%A5">消息去重策略</a></li><li><a href="#%E9%AB%98%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E6%8A%80%E5%B7%A7">高性能优化技巧</a></li><li><a href="#%E6%B6%88%E6%81%AF%E6%A0%BC%E5%BC%8F%E4%BC%98%E5%8C%96">消息格式优化</a></li></ul><hr><h2 id="核心问题" tabindex="-1"><a class="header-anchor" href="#核心问题"><span>核心问题</span></a></h2><p>当实体移动时，需要通知<strong>视野内所有玩家</strong>这个实体的状态变化。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">场景：怪物从A点移动到B点</span>
<span class="line">      👻 移动 →</span>
<span class="line"></span>
<span class="line">需要通知：</span>
<span class="line">- 怪物视野内所有玩家：怪物的新位置</span>
<span class="line">- 同时需要告诉玩家：哪些怪物进入/离开了视野</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="一、广播类型" tabindex="-1"><a class="header-anchor" href="#一、广播类型"><span>一、广播类型</span></a></h2><h3 id="_1-进入广播" tabindex="-1"><a class="header-anchor" href="#_1-进入广播"><span>1. 进入广播</span></a></h3><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token comment">// 玩家进入地图时</span></span>
<span class="line"><span class="token function">onPlayerEnter</span><span class="token punctuation">(</span>Player<span class="token operator">*</span> player<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 1. 获取玩家视野内的所有实体</span></span>
<span class="line">    <span class="token keyword">auto</span> entities <span class="token operator">=</span> aoi<span class="token punctuation">.</span><span class="token function">getEntitiesInPlayerView</span><span class="token punctuation">(</span>player<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 2. 通知玩家：这些实体在你视野内</span></span>
<span class="line">    <span class="token keyword">for</span> <span class="token punctuation">(</span>Entity<span class="token operator">*</span> e <span class="token operator">:</span> entities<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        player<span class="token operator">-&gt;</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token function">EntityAppearMsg</span><span class="token punctuation">(</span>e<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// &quot;怪物X出现在(x,y)&quot;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 3. 通知视野内玩家：有一个新玩家来了</span></span>
<span class="line">    <span class="token keyword">for</span> <span class="token punctuation">(</span>Entity<span class="token operator">*</span> e <span class="token operator">:</span> entities<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>e<span class="token operator">-&gt;</span><span class="token function">isPlayer</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            e<span class="token operator">-&gt;</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token function">PlayerEnterMsg</span><span class="token punctuation">(</span>player<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-离开广播" tabindex="-1"><a class="header-anchor" href="#_2-离开广播"><span>2. 离开广播</span></a></h3><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token comment">// 玩家离开时</span></span>
<span class="line"><span class="token function">onPlayerLeave</span><span class="token punctuation">(</span>Player<span class="token operator">*</span> player<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">auto</span> viewers <span class="token operator">=</span> aoi<span class="token punctuation">.</span><span class="token function">getViewers</span><span class="token punctuation">(</span>player<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 谁能看到我</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 通知所有能看到我的玩家：我离开了</span></span>
<span class="line">    <span class="token keyword">for</span> <span class="token punctuation">(</span>Entity<span class="token operator">*</span> viewer <span class="token operator">:</span> viewers<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        viewer<span class="token operator">-&gt;</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token function">EntityLeaveMsg</span><span class="token punctuation">(</span>player<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-移动广播-最复杂" tabindex="-1"><a class="header-anchor" href="#_3-移动广播-最复杂"><span>3. 移动广播（最复杂）</span></a></h3><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token comment">// 玩家/怪物移动时</span></span>
<span class="line"><span class="token function">onEntityMove</span><span class="token punctuation">(</span>Entity<span class="token operator">*</span> entity<span class="token punctuation">,</span> Position oldPos<span class="token punctuation">,</span> Position newPos<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 1. 计算旧的视野和新的视野</span></span>
<span class="line">    <span class="token keyword">auto</span> oldViewers <span class="token operator">=</span> <span class="token function">getEntityViewers</span><span class="token punctuation">(</span>oldPos<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">auto</span> newViewers <span class="token operator">=</span> <span class="token function">getEntityViewers</span><span class="token punctuation">(</span>newPos<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 2. 找出差异</span></span>
<span class="line">    <span class="token keyword">auto</span> enterViewers <span class="token operator">=</span> newViewers <span class="token operator">-</span> oldViewers<span class="token punctuation">;</span>  <span class="token comment">// 新看到的玩家</span></span>
<span class="line">    <span class="token keyword">auto</span> leaveViewers <span class="token operator">=</span> oldViewers <span class="token operator">-</span> newViewers<span class="token punctuation">;</span>  <span class="token comment">// 丢失视野的玩家</span></span>
<span class="line">    <span class="token keyword">auto</span> stayViewers   <span class="token operator">=</span> oldViewers <span class="token operator">&amp;</span> newViewers<span class="token punctuation">;</span>  <span class="token comment">// 一直看到的玩家</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 3. 分发消息</span></span>
<span class="line">    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">auto</span> viewer <span class="token operator">:</span> leaveViewers<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        viewer<span class="token operator">-&gt;</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token function">EntityLeaveMsg</span><span class="token punctuation">(</span>entity<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">auto</span> viewer <span class="token operator">:</span> enterViewers<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        viewer<span class="token operator">-&gt;</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token function">EntityAppearMsg</span><span class="token punctuation">(</span>entity<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">auto</span> viewer <span class="token operator">:</span> stayViewers<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        viewer<span class="token operator">-&gt;</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token function">EntityMoveMsg</span><span class="token punctuation">(</span>entity<span class="token punctuation">,</span> oldPos<span class="token punctuation">,</span> newPos<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 增量更新</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="二、消息去重策略" tabindex="-1"><a class="header-anchor" href="#二、消息去重策略"><span>二、消息去重策略</span></a></h2><h3 id="问题-消息风暴" tabindex="-1"><a class="header-anchor" href="#问题-消息风暴"><span>问题：消息风暴</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">一个格子里100个玩家同时移动</span>
<span class="line">→ 每个玩家通知99个其他玩家</span>
<span class="line">→ 100 * 99 = 9900 条消息</span>
<span class="line">→ 网络爆炸！</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="方案1-感兴趣列表-interest-list" tabindex="-1"><a class="header-anchor" href="#方案1-感兴趣列表-interest-list"><span>方案1: 感兴趣列表（Interest List）</span></a></h3><p>每个实体维护一个<strong>谁在看我</strong>的列表：</p><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token keyword">struct</span> <span class="token class-name">Entity</span> <span class="token punctuation">{</span></span>
<span class="line">    std<span class="token double-colon punctuation">::</span>unordered_set<span class="token operator">&lt;</span>Entity<span class="token operator">*</span><span class="token operator">&gt;</span> viewers<span class="token punctuation">;</span>  <span class="token comment">// 谁在看我</span></span>
<span class="line">    std<span class="token double-colon punctuation">::</span>unordered_set<span class="token operator">&lt;</span>Entity<span class="token operator">*</span><span class="token operator">&gt;</span> watchees<span class="token punctuation">;</span> <span class="token comment">// 我在看谁</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">void</span> <span class="token function">updateViewers</span><span class="token punctuation">(</span>Entity<span class="token operator">*</span> entity<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">auto</span> newViewers <span class="token operator">=</span> aoi<span class="token punctuation">.</span><span class="token function">getViewers</span><span class="token punctuation">(</span>entity<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// O(9格)</span></span>
<span class="line">    <span class="token keyword">auto</span> oldViewers <span class="token operator">=</span> entity<span class="token operator">-&gt;</span>viewers<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 新增的观察者</span></span>
<span class="line">    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">auto</span> v <span class="token operator">:</span> newViewers <span class="token operator">-</span> oldViewers<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        entity<span class="token operator">-&gt;</span>viewers<span class="token punctuation">.</span><span class="token function">insert</span><span class="token punctuation">(</span>v<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        v<span class="token operator">-&gt;</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token function">EntityAppearMsg</span><span class="token punctuation">(</span>entity<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 离开的观察者</span></span>
<span class="line">    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">auto</span> v <span class="token operator">:</span> oldViewers <span class="token operator">-</span> newViewers<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        entity<span class="token operator">-&gt;</span>viewers<span class="token punctuation">.</span><span class="token function">erase</span><span class="token punctuation">(</span>v<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        v<span class="token operator">-&gt;</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token function">EntityLeaveMsg</span><span class="token punctuation">(</span>entity<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>优势</strong>：</p><ul><li>只在视野变化时计算，增量更新</li><li>避免每次移动都遍历九宫格</li></ul><h3 id="方案2-九宫格交叉去重" tabindex="-1"><a class="header-anchor" href="#方案2-九宫格交叉去重"><span>方案2: 九宫格交叉去重</span></a></h3><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token comment">// 核心思想：每个格子维护自己的广播列表</span></span>
<span class="line"><span class="token keyword">class</span> <span class="token class-name">Grid</span> <span class="token punctuation">{</span></span>
<span class="line">    std<span class="token double-colon punctuation">::</span>vector<span class="token operator">&lt;</span>Entity<span class="token operator">*</span><span class="token operator">&gt;</span> entities<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 本格子的实体需要广播给哪些格子？</span></span>
<span class="line">    std<span class="token double-colon punctuation">::</span>unordered_set<span class="token operator">&lt;</span>Grid<span class="token operator">*</span><span class="token operator">&gt;</span> broadcastTargets<span class="token punctuation">;</span>  <span class="token comment">// 需要通知的格子</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">void</span> <span class="token function">broadcastMove</span><span class="token punctuation">(</span>Entity<span class="token operator">*</span> mover<span class="token punctuation">,</span> Grid<span class="token operator">*</span> oldGrid<span class="token punctuation">,</span> Grid<span class="token operator">*</span> newGrid<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 1. 收集需要通知的格子（去重）</span></span>
<span class="line">    std<span class="token double-colon punctuation">::</span>unordered_set<span class="token operator">&lt;</span>Grid<span class="token operator">*</span><span class="token operator">&gt;</span> targetGrids<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">auto</span><span class="token operator">*</span> grid <span class="token operator">:</span> oldGrid<span class="token operator">-&gt;</span>broadcastTargets<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        targetGrids<span class="token punctuation">.</span><span class="token function">insert</span><span class="token punctuation">(</span>grid<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">auto</span><span class="token operator">*</span> grid <span class="token operator">:</span> newGrid<span class="token operator">-&gt;</span>broadcastTargets<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        targetGrids<span class="token punctuation">.</span><span class="token function">insert</span><span class="token punctuation">(</span>grid<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 2. 向每个目标格子广播一次</span></span>
<span class="line">    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">auto</span><span class="token operator">*</span> grid <span class="token operator">:</span> targetGrids<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">auto</span><span class="token operator">*</span> entity <span class="token operator">:</span> grid<span class="token operator">-&gt;</span>entities<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token punctuation">(</span>entity <span class="token operator">!=</span> mover<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                entity<span class="token operator">-&gt;</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token function">EntityMoveMsg</span><span class="token punctuation">(</span>mover<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="方案3-消息聚合-message-batching" tabindex="-1"><a class="header-anchor" href="#方案3-消息聚合-message-batching"><span>方案3: 消息聚合（Message Batching）</span></a></h3><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token comment">// 批量发送，减少网络包数量</span></span>
<span class="line"><span class="token keyword">class</span> <span class="token class-name">MessageBatcher</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">struct</span> <span class="token class-name">PendingMessage</span> <span class="token punctuation">{</span></span>
<span class="line">        std<span class="token double-colon punctuation">::</span>vector<span class="token operator">&lt;</span>EntityMoveData<span class="token operator">&gt;</span> moves<span class="token punctuation">;</span></span>
<span class="line">        std<span class="token double-colon punctuation">::</span>vector<span class="token operator">&lt;</span>EntityAppearData<span class="token operator">&gt;</span> appears<span class="token punctuation">;</span></span>
<span class="line">        std<span class="token double-colon punctuation">::</span>vector<span class="token operator">&lt;</span>EntityLeaveData<span class="token operator">&gt;</span> leaves<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    std<span class="token double-colon punctuation">::</span>unordered_map<span class="token operator">&lt;</span>Player<span class="token operator">*</span><span class="token punctuation">,</span> PendingMessage<span class="token operator">&gt;</span> pending<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">addMove</span><span class="token punctuation">(</span>Player<span class="token operator">*</span> receiver<span class="token punctuation">,</span> Entity<span class="token operator">*</span> mover<span class="token punctuation">,</span> Pos from<span class="token punctuation">,</span> Pos to<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        pending<span class="token punctuation">[</span>receiver<span class="token punctuation">]</span><span class="token punctuation">.</span>moves<span class="token punctuation">.</span><span class="token function">push_back</span><span class="token punctuation">(</span><span class="token punctuation">{</span>mover<span class="token operator">-&gt;</span>id<span class="token punctuation">,</span> from<span class="token punctuation">,</span> to<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">flush</span><span class="token punctuation">(</span><span class="token keyword">int</span> maxDelayMs<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// 定时批量发送</span></span>
<span class="line">        <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">auto</span><span class="token operator">&amp;</span> <span class="token punctuation">[</span>player<span class="token punctuation">,</span> msg<span class="token punctuation">]</span> <span class="token operator">:</span> pending<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>msg<span class="token punctuation">.</span>moves<span class="token punctuation">.</span><span class="token function">empty</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                player<span class="token operator">-&gt;</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token function">BatchMoveMsg</span><span class="token punctuation">(</span>msg<span class="token punctuation">.</span>moves<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 一次包发多个移动</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">        pending<span class="token punctuation">.</span><span class="token function">clear</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 使用：每50ms批量发送一次</span></span>
<span class="line">MessageBatcher batcher<span class="token punctuation">;</span></span>
<span class="line">timer<span class="token punctuation">.</span><span class="token function">every</span><span class="token punctuation">(</span><span class="token number">50</span>ms<span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token operator">&amp;</span><span class="token punctuation">]</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> batcher<span class="token punctuation">.</span><span class="token function">flush</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="三、完整广播实现" tabindex="-1"><a class="header-anchor" href="#三、完整广播实现"><span>三、完整广播实现</span></a></h2><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token keyword">class</span> <span class="token class-name">AOIBroadcaster</span> <span class="token punctuation">{</span></span>
<span class="line"><span class="token keyword">public</span><span class="token operator">:</span></span>
<span class="line">    <span class="token comment">// 实体移动时的广播</span></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">onMove</span><span class="token punctuation">(</span>Entity<span class="token operator">*</span> entity<span class="token punctuation">,</span> Position from<span class="token punctuation">,</span> Position to<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// 1. 计算视野变化</span></span>
<span class="line">        ViewChange change <span class="token operator">=</span> <span class="token function">calculateViewChange</span><span class="token punctuation">(</span>from<span class="token punctuation">,</span> to<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 2. 处理离开视野的玩家</span></span>
<span class="line">        <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">auto</span><span class="token operator">*</span> leaver <span class="token operator">:</span> change<span class="token punctuation">.</span>leavers<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            entity<span class="token operator">-&gt;</span><span class="token function">removeWatcher</span><span class="token punctuation">(</span>leaver<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            leaver<span class="token operator">-&gt;</span><span class="token function">send</span><span class="token punctuation">(</span>EntityLeave<span class="token punctuation">{</span>entity<span class="token operator">-&gt;</span>id<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 3. 处理进入视野的玩家</span></span>
<span class="line">        <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">auto</span><span class="token operator">*</span> enterer <span class="token operator">:</span> change<span class="token punctuation">.</span>enterers<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            entity<span class="token operator">-&gt;</span><span class="token function">addWatcher</span><span class="token punctuation">(</span>enterer<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            enterer<span class="token operator">-&gt;</span><span class="token function">send</span><span class="token punctuation">(</span>EntityAppear<span class="token punctuation">{</span>entity<span class="token operator">-&gt;</span>id<span class="token punctuation">,</span> to<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 4. 处理一直在视野内的玩家（发送移动消息）</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>change<span class="token punctuation">.</span>stayers<span class="token punctuation">.</span><span class="token function">empty</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token comment">// 去重：同一帧内只发送一次</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>entity<span class="token operator">-&gt;</span><span class="token function">hasMoveFlagThisFrame</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">auto</span><span class="token operator">*</span> stayer <span class="token operator">:</span> change<span class="token punctuation">.</span>stayers<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                    stayer<span class="token operator">-&gt;</span><span class="token function">send</span><span class="token punctuation">(</span>EntityMove<span class="token punctuation">{</span>entity<span class="token operator">-&gt;</span>id<span class="token punctuation">,</span> from<span class="token punctuation">,</span> to<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">                <span class="token punctuation">}</span></span>
<span class="line">                entity<span class="token operator">-&gt;</span><span class="token function">setMoveFlag</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 定时清理标记（每帧清理）</span></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">clearFlags</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">auto</span><span class="token operator">*</span> entity <span class="token operator">:</span> allEntities<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            entity<span class="token operator">-&gt;</span><span class="token function">clearMoveFlag</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">private</span><span class="token operator">:</span></span>
<span class="line">    <span class="token keyword">struct</span> <span class="token class-name">ViewChange</span> <span class="token punctuation">{</span></span>
<span class="line">        std<span class="token double-colon punctuation">::</span>vector<span class="token operator">&lt;</span>Entity<span class="token operator">*</span><span class="token operator">&gt;</span> leavers<span class="token punctuation">;</span>  <span class="token comment">// 离开视野的</span></span>
<span class="line">        std<span class="token double-colon punctuation">::</span>vector<span class="token operator">&lt;</span>Entity<span class="token operator">*</span><span class="token operator">&gt;</span> enterers<span class="token punctuation">;</span> <span class="token comment">// 进入视野的</span></span>
<span class="line">        std<span class="token double-colon punctuation">::</span>vector<span class="token operator">&lt;</span>Entity<span class="token operator">*</span><span class="token operator">&gt;</span> stayers<span class="token punctuation">;</span>  <span class="token comment">// 一直在的</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    ViewChange <span class="token function">calculateViewChange</span><span class="token punctuation">(</span>Position from<span class="token punctuation">,</span> Position to<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        ViewChange result<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token keyword">auto</span> oldViewers <span class="token operator">=</span> <span class="token function">getViewers</span><span class="token punctuation">(</span>from<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 旧位置能看到谁</span></span>
<span class="line">        <span class="token keyword">auto</span> newViewers <span class="token operator">=</span> <span class="token function">getViewers</span><span class="token punctuation">(</span>to<span class="token punctuation">)</span><span class="token punctuation">;</span>    <span class="token comment">// 新位置能看到谁</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 计算差集（去重关键）</span></span>
<span class="line">        <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">auto</span><span class="token operator">*</span> v <span class="token operator">:</span> oldViewers<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token punctuation">(</span>newViewers<span class="token punctuation">.</span><span class="token function">count</span><span class="token punctuation">(</span>v<span class="token punctuation">)</span> <span class="token operator">==</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                result<span class="token punctuation">.</span>leavers<span class="token punctuation">.</span><span class="token function">push_back</span><span class="token punctuation">(</span>v<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">                result<span class="token punctuation">.</span>stayers<span class="token punctuation">.</span><span class="token function">push_back</span><span class="token punctuation">(</span>v<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">        <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">auto</span><span class="token operator">*</span> v <span class="token operator">:</span> newViewers<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token punctuation">(</span>oldViewers<span class="token punctuation">.</span><span class="token function">count</span><span class="token punctuation">(</span>v<span class="token punctuation">)</span> <span class="token operator">==</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                result<span class="token punctuation">.</span>enterers<span class="token punctuation">.</span><span class="token function">push_back</span><span class="token punctuation">(</span>v<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">        <span class="token keyword">return</span> result<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="四、高性能优化技巧" tabindex="-1"><a class="header-anchor" href="#四、高性能优化技巧"><span>四、高性能优化技巧</span></a></h2><h3 id="_1-对象池复用消息对象" tabindex="-1"><a class="header-anchor" href="#_1-对象池复用消息对象"><span>1. 对象池复用消息对象</span></a></h3><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token comment">// 避免频繁分配消息对象</span></span>
<span class="line"><span class="token keyword">class</span> <span class="token class-name">MessagePool</span> <span class="token punctuation">{</span></span>
<span class="line">    std<span class="token double-colon punctuation">::</span>vector<span class="token operator">&lt;</span>EntityMoveMsg<span class="token operator">*</span><span class="token operator">&gt;</span> freeList<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    EntityMoveMsg<span class="token operator">*</span> <span class="token function">acquire</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>freeList<span class="token punctuation">.</span><span class="token function">empty</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token function">EntityMoveMsg</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">        <span class="token keyword">auto</span><span class="token operator">*</span> msg <span class="token operator">=</span> freeList<span class="token punctuation">.</span><span class="token function">back</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        freeList<span class="token punctuation">.</span><span class="token function">pop_back</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">return</span> msg<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">release</span><span class="token punctuation">(</span>EntityMoveMsg<span class="token operator">*</span> msg<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        msg<span class="token operator">-&gt;</span><span class="token function">reset</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        freeList<span class="token punctuation">.</span><span class="token function">push_back</span><span class="token punctuation">(</span>msg<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-区域广播-zone-broadcast" tabindex="-1"><a class="header-anchor" href="#_2-区域广播-zone-broadcast"><span>2. 区域广播（Zone Broadcast）</span></a></h3><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token comment">// 将地图划分为区域，区域内统一广播</span></span>
<span class="line"><span class="token keyword">class</span> <span class="token class-name">BroadcastZone</span> <span class="token punctuation">{</span></span>
<span class="line">    std<span class="token double-colon punctuation">::</span>vector<span class="token operator">&lt;</span>Entity<span class="token operator">*</span><span class="token operator">&gt;</span> entities<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">broadcast</span><span class="token punctuation">(</span><span class="token keyword">const</span> IMessage<span class="token operator">&amp;</span> msg<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">auto</span><span class="token operator">*</span> e <span class="token operator">:</span> entities<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            e<span class="token operator">-&gt;</span><span class="token function">send</span><span class="token punctuation">(</span>msg<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 使用：相同区域的消息合并</span></span>
<span class="line">zone<span class="token punctuation">.</span><span class="token function">broadcast</span><span class="token punctuation">(</span>BatchMoveMsg<span class="token punctuation">{</span>allMovesInThisZone<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-层次化aoi-多级九宫格" tabindex="-1"><a class="header-anchor" href="#_3-层次化aoi-多级九宫格"><span>3. 层次化AOI（多级九宫格）</span></a></h3><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token comment">// 远距离用大格子，近距离用小格子</span></span>
<span class="line"><span class="token keyword">class</span> <span class="token class-name">HierarchicalAOI</span> <span class="token punctuation">{</span></span>
<span class="line">    NineGrid coarseGrid<span class="token punctuation">;</span>  <span class="token comment">// 1000m × 1000m 粗粒度</span></span>
<span class="line">    NineGrid fineGrid<span class="token punctuation">;</span>    <span class="token comment">// 100m × 100m  细粒度</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">broadcastMove</span><span class="token punctuation">(</span>Entity<span class="token operator">*</span> e<span class="token punctuation">,</span> Pos from<span class="token punctuation">,</span> Pos to<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// 远距离玩家：只通知大格子</span></span>
<span class="line">        coarseGrid<span class="token punctuation">.</span><span class="token function">broadcastMove</span><span class="token punctuation">(</span>e<span class="token punctuation">,</span> from<span class="token punctuation">,</span> to<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 近距离玩家：通知小格子</span></span>
<span class="line">        fineGrid<span class="token punctuation">.</span><span class="token function">broadcastMove</span><span class="token punctuation">(</span>e<span class="token punctuation">,</span> from<span class="token punctuation">,</span> to<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="五、消息格式优化" tabindex="-1"><a class="header-anchor" href="#五、消息格式优化"><span>五、消息格式优化</span></a></h2><h3 id="压缩消息结构" tabindex="-1"><a class="header-anchor" href="#压缩消息结构"><span>压缩消息结构</span></a></h3><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token comment">// 优化前：每个移动50字节</span></span>
<span class="line"><span class="token keyword">struct</span> <span class="token class-name">MoveMsg_v1</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">uint64_t</span> entityId<span class="token punctuation">;</span>   <span class="token comment">// 8字节</span></span>
<span class="line">    <span class="token keyword">float</span> fromX<span class="token punctuation">,</span> fromY<span class="token punctuation">;</span>  <span class="token comment">// 8字节</span></span>
<span class="line">    <span class="token keyword">float</span> toX<span class="token punctuation">,</span> toY<span class="token punctuation">;</span>      <span class="token comment">// 8字节</span></span>
<span class="line">    <span class="token keyword">uint32_t</span> timestamp<span class="token punctuation">;</span>  <span class="token comment">// 4字节</span></span>
<span class="line">    <span class="token comment">// ... 共50字节</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 优化后：每个移动15字节（打包发送）</span></span>
<span class="line"><span class="token keyword">struct</span> <span class="token class-name">BatchMoveMsg</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">uint16_t</span> count<span class="token punctuation">;</span>      <span class="token comment">// 数量</span></span>
<span class="line">    <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">uint32_t</span> entityId <span class="token operator">:</span> <span class="token number">24</span><span class="token punctuation">;</span>  <span class="token comment">// 3字节（最多1600万实体）</span></span>
<span class="line">        <span class="token keyword">int16_t</span> deltaX <span class="token operator">:</span> <span class="token number">11</span><span class="token punctuation">;</span>     <span class="token comment">// 2字节（-1024~1023，相对坐标）</span></span>
<span class="line">        <span class="token keyword">int16_t</span> deltaY <span class="token operator">:</span> <span class="token number">11</span><span class="token punctuation">;</span>     <span class="token comment">// 2字节</span></span>
<span class="line">    <span class="token punctuation">}</span> moves<span class="token punctuation">[</span><span class="token number">100</span><span class="token punctuation">]</span><span class="token punctuation">;</span>  <span class="token comment">// 一次发送100个移动</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 100个移动 = 2 + 100*7 = 702字节</span></span>
<span class="line">    <span class="token comment">// 平均每个 = 7字节</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="总结" tabindex="-1"><a class="header-anchor" href="#总结"><span>总结</span></a></h2><table><thead><tr><th>问题</th><th>解决方案</th></tr></thead><tbody><tr><td><strong>广播给谁</strong></td><td>维护观察者列表，增量更新</td></tr><tr><td><strong>消息去重</strong></td><td>位标记法 + 感兴趣列表</td></tr><tr><td><strong>性能优化</strong></td><td>批量发送、对象池、消息压缩</td></tr><tr><td><strong>消息风暴</strong></td><td>区域广播 + 层次化AOI</td></tr></tbody></table><p>核心思想：<strong>只通知变化，避免重复，批量发送</strong></p>`,47)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};